-- ============================================================================
-- Ajuste masivo de inventario - Bodega PRINCIPAL
-- Origen: ExportExcel 21 mayo.xlsx (3722 productos)
-- Fecha generacion: 2026-05-21
-- ============================================================================
-- COMPORTAMIENTO:
--   * Crea los productos cuyo codigo_barras no exista (defaults: tipo=0,
--     id_unidad=1, estado=true, precios y stock_min/ideal vacios).
--   * Crea UNA cabecera de ajuste para bodega PRINCIPAL (id=1) con id_user=1
--     (admin). Cambialos en las variables v_id_user / v_id_bodega si lo
--     necesitas.
--   * Para cada producto cuyo stock fisico difiera del valor del Excel:
--       - Inserta detalle en ajustes_inventario_detalle
--       - Registra movimiento en movimientos_inventario (snapshot antes/despues)
--       - Hace UPSERT en stock_productos
--   * Los productos cuyo stock ya coincida con el Excel NO generan filas.
--   * Todo va en una sola transaccion; si algo falla se hace ROLLBACK completo.
--
-- COMO EJECUTAR (Windows / PostgreSQL 9.4):
--   set PGPASSWORD=monkey
--   psql -h localhost -p 5432 -U postgres -d bodega_tecnirepuestos ^
--        -v ON_ERROR_STOP=1 -f ajuste_inventario_2026-05-21.sql
--
-- BACKUP recomendado antes de correr en produccion:
--   pg_dump -h localhost -p 5432 -U postgres -F c ^
--           -f backup_pre_ajuste.dump bodega_tecnirepuestos
-- ============================================================================

\set ON_ERROR_STOP on

BEGIN;

