-- ----------------------------------------------------------------------------
-- 2) Bloque procedural: crea productos faltantes, genera cabecera y aplica
--    los ajustes uno a uno.
-- ----------------------------------------------------------------------------
DO $BLOQUE$
DECLARE
    v_id_user       INT := 1;        -- admin
    v_id_bodega     INT := 1;        -- PRINCIPAL
    v_observacion   VARCHAR(500) := 'Ajuste masivo desde Excel (ExportExcel 21 mayo.xlsx)';
    v_hora          VARCHAR(8) := TO_CHAR(NOW(), 'HH24:MI:SS');
    v_id_cab        INT;
    v_id_prod       INT;
    v_cant_ant      DOUBLE PRECISION;
    v_cant_nue      DOUBLE PRECISION;
    v_pend_ant      DOUBLE PRECISION;
    v_costo_prom    DOUBLE PRECISION;
    v_diferencia    DOUBLE PRECISION;
    v_creados       INT := 0;
    v_ajustados     INT := 0;
    v_sin_cambios   INT := 0;
    r               RECORD;
BEGIN
    -- 2.1 Crear productos faltantes
    INSERT INTO productos (codigo_barras, descripcion, tipo, id_unidad, estado)
    SELECT s.codigo, s.descripcion, 0, 1, true
      FROM _staging_ajuste s
     WHERE NOT EXISTS (
            SELECT 1 FROM productos p WHERE p.codigo_barras = s.codigo
     );
    GET DIAGNOSTICS v_creados = ROW_COUNT;
    RAISE NOTICE 'Productos nuevos creados: %', v_creados;

    -- 2.2 Cabecera del ajuste
    INSERT INTO ajustes_inventario_cabecera
        (fecha, hora, id_user, id_bodega, observacion, estado)
    VALUES (CURRENT_DATE, v_hora, v_id_user, v_id_bodega, v_observacion, 1)
    RETURNING id INTO v_id_cab;
    RAISE NOTICE 'Cabecera de ajuste creada con id = %', v_id_cab;

    -- 2.3 Recorrer cada producto del staging y aplicar
    FOR r IN
        SELECT s.codigo, s.cant_nueva, p.id AS id_producto
          FROM _staging_ajuste s
          JOIN productos p ON p.codigo_barras = s.codigo
         ORDER BY s.codigo
    LOOP
        v_id_prod  := r.id_producto;
        v_cant_nue := r.cant_nueva;

        -- Stock actual (con FOR UPDATE para serializar)
        SELECT cantidad, pendientes, COALESCE(costo_promedio,0)
          INTO v_cant_ant, v_pend_ant, v_costo_prom
          FROM stock_productos
         WHERE id_producto = v_id_prod AND id_bodega = v_id_bodega
           FOR UPDATE;

        IF NOT FOUND THEN
            v_cant_ant   := 0;
            v_pend_ant   := 0;
            v_costo_prom := 0;
            INSERT INTO stock_productos
                (id_producto, id_bodega, cantidad, pendientes, costo_promedio)
            VALUES (v_id_prod, v_id_bodega, 0, 0, 0);
        END IF;

        v_diferencia := v_cant_nue - v_cant_ant;

        IF v_diferencia = 0 THEN
            v_sin_cambios := v_sin_cambios + 1;
            CONTINUE;
        END IF;

        -- Detalle del ajuste
        INSERT INTO ajustes_inventario_detalle
            (id_ajuste_cabecera, id_producto,
             cantidad_anterior, cantidad_nueva, diferencia,
             pendientes_anterior, pendientes_nuevo, diferencia_pendientes,
             observacion)
        VALUES (v_id_cab, v_id_prod,
                v_cant_ant, v_cant_nue, v_diferencia,
                v_pend_ant, v_pend_ant, 0,
                NULL);

        -- Movimiento de inventario (snapshot antes/despues)
        INSERT INTO movimientos_inventario
            (id_producto, id_bodega, id_user,
             tipo, afecta_cantidad, afecta_pendientes, valor,
             valor_anterior, valor_nuevo,
             costo_unitario, costo_promedio_anterior, costo_promedio_nuevo,
             cantidad_anterior, cantidad_nueva, pendientes_anterior, pendientes_nuevo,
             id_referencia, tabla_referencia, fecha, hora, observacion)
        VALUES
            (v_id_prod, v_id_bodega, v_id_user,
             CASE WHEN v_diferencia > 0 THEN 'AJUSTE_POSITIVO' ELSE 'AJUSTE_NEGATIVO' END,
             CASE WHEN v_diferencia > 0 THEN 1 ELSE -1 END, 0, ABS(v_diferencia),
             NULL, NULL,
             NULL, v_costo_prom, v_costo_prom,
             v_cant_ant, v_cant_nue, v_pend_ant, v_pend_ant,
             v_id_cab, 'ajustes_inventario_cabecera',
             CURRENT_DATE, v_hora,
             'Ajuste #' || v_id_cab);

        -- Actualizar stock fisico
        UPDATE stock_productos
           SET cantidad   = v_cant_nue,
               updated_at = now()
         WHERE id_producto = v_id_prod AND id_bodega = v_id_bodega;

        v_ajustados := v_ajustados + 1;
    END LOOP;

    RAISE NOTICE '----------------------------------------';
    RAISE NOTICE 'RESUMEN AJUSTE #%', v_id_cab;
    RAISE NOTICE '  Productos creados      : %', v_creados;
    RAISE NOTICE '  Productos ajustados    : %', v_ajustados;
    RAISE NOTICE '  Productos sin cambios  : %', v_sin_cambios;
    RAISE NOTICE '  Total procesados       : %', v_ajustados + v_sin_cambios;
    RAISE NOTICE '----------------------------------------';
END
$BLOQUE$;

COMMIT;

